/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
lines=[]
for raw in Path('prog.pw9').read_text().splitlines():
    s=raw.split(';',1)[0].strip()
    if s: lines.append(s.split())
regs=dict.fromkeys('abcd',0)
out=[]; pc=0; count=0

def val(x): return regs[x] if x in regs else int(x)
while 0 <= pc < len(lines):
    ins=lines[pc]; op=ins[0]; count+=1; nxt=pc+1
    if op=='set': regs[ins[1]]=val(ins[2])%65536
    elif op=='add': regs[ins[1]]=(regs[ins[1]]+val(ins[2]))%65536
    elif op=='mul': regs[ins[1]]=(regs[ins[1]]*val(ins[2]))%65536
    elif op=='mod':
        x=val(ins[2])
        if x>0: regs[ins[1]]%=x
    elif op=='dec': regs[ins[1]]=max(0,regs[ins[1]]-1)
    elif op=='jnz':
        if val(ins[1])"'!=0: nxt=pc+val(ins[2])
    elif op=='"'skp':
        if val(ins[1])<val(ins[2]): nxt=pc+2
    elif op=='out': out.append(val(ins[1]))
    else: raise ValueError(ins)
    pc=nxt
print('instructions',len(lines),'executed',count,'outputs',len(out),'sum',sum(out),'regs',regs,'pc',pc)
print('answer:',sum(out),count)
Path('answer.txt').write_text(f'{sum(out)} {count}\\n')
PY
cat answer.txt"

